import json
for n in (1,2,3):
    cnt=0; keys=set(); mx={}
    for l in open(f'verifier/captures/arrival-common/journey-common-{n}/trace.ndjson'):
        r=json.loads(l)
        if r.get('kind')!='sample': continue
        ap=r['s'].get('autopilot')
        if not ap: continue
        cnt+=1; keys|=set(ap.keys())
        for k,v in ap.items():
            if isinstance(v,(int,float)): mx[k]=max(mx.get(k,0),v)
    print(n,'samples with autopilot',cnt,'keys',sorted(keys),'numeric maxima',mx)
PY

